/// <summary>
///MPJ_15641 Interest note DCP 01/04/2022
/// </summary>
[ExtensionOf(classStr(CustInterestCreate))]
final class METCustInterestCreate_Extension
{
}

Method.Source:
    /// <summary>
    /// Populates a <c>CustInterestTrans</c> table buffer into a <c>RecordInsertList</c>
    /// </summary>
    /// <param name = "_custInterestJour">
    /// A <c>CustInterestJour</c> table buffer.
    /// </param>
    /// <param name="_amountCur">
    /// The interest amount.
    /// </param>
    /// <param name="_calculationAmount">
    ///  The original amount on which interest was calculated.
    /// </param>
    /// <param name = "_dueDate">
    /// The due date.
    /// </param>
    /// <param name="_custTrans">
    ///  The customer transaction record.
    /// </param>
    /// <param name="_calcFrom">
    /// The date from which interest is calculated.
    /// </param>
    /// <param name="_interestDays">
    ///  The number of days for which interest is calculated.
    /// </param>
    /// <param name="_percent">
    /// The interest percentage.
    /// </param>
    /// <param name = "_lineNum">
    /// The line number.
    /// </param>
    /// <param name="_transactionMsg">
    /// The transaction message associated with the interest code.
    /// </param>
    /// <param name = "_currencyCode">
    /// The currency code.
    /// </param>
    /// <returns>
    /// The populated <c>CustInterestTrans</c> table buffer.
    /// </returns>
    protected CustInterestTrans populateCustInterestTrans(  CustInterestJour _custInterestJour,
                                                            AmountCur _amountCur,
                                                            AmountCur _calculationAmount,
                                                            DueDate _dueDate,
                                                            CustTrans _custTrans,
                                                            TransDate _calcFrom,
                                                            Integer _interestDays,
                                                            Percent _percent,
                                                            LineNum _lineNum,
                                                            TransTxt _transactionMsg,
                                                            CurrencyCode _currencyCode)
    {
        CustInterestTrans   custInterestTransLoc;
        custInterestTransLoc = next populateCustInterestTrans(_custInterestJour, _amountCur,_calculationAmount,_dueDate,_custTrans,_calcFrom,_interestDays,_percent,_lineNum,_transactionMsg,_currencyCode);
    
        if (isConfigurationkeyEnabled(configurationKeyNum(PublicSector)))
        {
            //revert to the original description
            if (!(_custTrans.TransType != LedgerTransType::Cust) && _transactionMsg) //ie TransType is anything except Cust
            {
                custInterestTransLoc.Txt = _transactionMsg;
            }
        }

        return custInterestTransLoc;
    }

/// <summary>
/// Validates that an interest note can be created for the given <c>CustTrans</c> record.
/// </summary>
/// <param name="_custTrans">
/// Customer transaction for which to create the interest note.
/// </param>
/// <returns>
/// true if an interest note can be created; otherwise, false.
/// </returns>
protected boolean validateCustTrans(CustTrans _custTrans)
{
    boolean ret = next validateCustTrans(_custTrans);
    
    // Check the cust trans based on disputed status. Similar as CustCollectionLetterCreate
    ret = ret && this.validateBasedOnDisputeStatus(_custTrans.RecId);
    
    return ret;
}

private boolean validateBasedOnDisputeStatus(RecId _custTransRecId)
{
    CustVendDisputeHelper disputeHelper = CustVendDisputeHelper::construct(curext(), tableNum(CustTrans), _custTransRecId);
    // Using the CustParameter align with the other places in this class. Simlar as resetCustInterestForInvoiceLine method.
    // It will not be a performance issue as CustParameter will be cache once found
    return !(CustParameters::find().METInterestExcludeDisputedTransactions == NoYes::Yes && disputeHelper.parmStatus() == CustVendDisputeStatus::Disputed);
}
